function hitsCollider(x,z){const list=state.interiorMode==='mine'?mineColliders:state.interiorMode==='ruin'?ruinColliders:state.interior?interiorColliders:colliders;if(!state.interior&&trees.some(t=>dist2(x,z,t.x,t.z)<t.r*.72))return true;return list.some(c=>x>c.x-c.hx&&x<c.x+c.hx&&z>c.z-c.hz&&z<c.z+c.hz)}

