function pine(x,z,s=1){const y=heightAt(x,z),g=new THREE.Group();g.position.set(x,y,z);const trunk=mesh(new THREE.CylinderGeometry(.18*s,.28*s,3.8*s,6),material(0x4a3525,.95),0,1.9*s,0,g);for(let j=0;j<3;j++){const crown=mesh(new THREE.ConeGeometry((1.9-j*.36)*s,4.1*s,7),material(j?0x173321:0x1d4329,.95),0,(3.8+j*1.45)*s,0,g);crown.rotation.y=Math.random()*2}worldGroup.add(g);trees.push({x,z,r:1.1*s,g});return g}
